const customerMessage = $('When chat message received').first().json.chatInput || '';

const aiResponse = $json.text || '';

const message = customerMessage.toLowerCase();

let category = 'General';

// 1. Payment-related enquiries
if (/\b(payment|paid|charge|charged|billing|refund|transaction|invoice|debit|deducted|overcharged)\b/.test(message)) {
  category = 'Payments';
}

// 2. Delivery-related enquiries
else if (/\b(delivery|deliver|shipping|shipped|dispatch|tracking|courier|package)\b/.test(message)) {
  category = 'Delivery';
}

// 3. Complaint-related enquiries
else if (/\b(complaint|damaged|defective|broken|poor service|unhappy|dissatisfied|disappointed)\b/.test(message)) {
  category = 'Complaints';
}

// 4. Order-related enquiries
else if (/\b(order|purchase|buy|buying|ordered|cancel my order)\b/.test(message)) {
  category = 'Orders';
}

// 5. General enquiries
else {
  category = 'General';
}

// Determine customer enquiry status
let status = 'Pending';

if (category === 'Complaints') {
  status = 'Needs Human Review';
}

// Return all information to Google Sheets
return [
  {
    json: {
      text: aiResponse,
      customerMessage: customerMessage,
      category: category,
      status: status
    }
  }
];

const customerMessage = $('When chat message received').first().json.chatInput || '';

const knowledgeRows = $input.all().map(item => item.json);

const knowledgeBase = knowledgeRows.map(row => {
  return `Category: ${row.Category}
Question: ${row.Question}
Answer: ${row.Answer}`;
}).join('\n\n');

return [
  {
    json: {
      customerMessage,
      knowledgeBase
    }
  }
];

const customerMessage = ($json.customerMessage || '').toLowerCase();

const knowledgeRows = $('Get row(s) in sheet').all()
  .map(item => item.json);

const intents = [
  {
    name: 'opening hours',
    pattern: /opening hours|business hours|what time.*open|when.*open|when.*close/
  },
  {
    name: 'delivery time',
    pattern: /how long.*delivery|delivery time|when.*arrive/
  },
  {
    name: 'delivery availability',
    pattern: /offer delivery|do you deliver|deliver to customers/
  },
  {
    name: 'payments',
    pattern: /payment method|how.*pay|payment options/
  },
  {
    name: 'returns',
    pattern: /return.*product|return policy|refund/
  },
  {
    name: 'orders',
    pattern: /place.*order|how.*order/
  },
  {
    name: 'business products',
    pattern: /what do you sell|what products/
  }
];

const intent = intents.find(item => item.pattern.test(customerMessage));

let matchingEntry = '';

if (intent) {
  const relevantRow = knowledgeRows.find(row => {
    const question = (row.Question || '').toLowerCase();

    if (intent.name === 'opening hours') {
      return /opening hours|business hours/.test(question);
    }

    if (intent.name === 'delivery time') {
      return /how long does delivery take|delivery time/.test(question);
    }

    if (intent.name === 'delivery availability') {
      return /offer delivery|do you offer delivery/.test(question);
    }

    if (intent.name === 'payments') {
      return /payment methods|payment options/.test(question);
    }

    if (intent.name === 'returns') {
      return /return a product|return policy/.test(question);
    }

    if (intent.name === 'orders') {
      return /place an order/.test(question);
    }

    if (intent.name === 'business products') {
      return /what do you sell|what products/.test(question);
    }

    return false;
  });

  if (relevantRow) {
    matchingEntry = relevantRow.Answer || '';
  }
}

return [{
  json: {
    customerMessage: $json.customerMessage,
    knowledgeBase: $json.knowledgeBase,
    knowledgeFound: Boolean(matchingEntry),
    matchingEntry
  }
}];

